protocol Comparable {
    static func less(_ a: Self, _ b: Self) -> Bool
}

extension Comparable {                       // default = mixin
    static func greater(_ a: Self, _ b: Self) -> Bool { less(b, a) }
}

func maxOf<T: Comparable>(_ a: T, _ b: T) -> T { T.less(a, b) ? b : a }  // static dispatch
